CREATE OR REPLACE FUNCTION public.resolve_student_organization_participation(target_student_id integer, target_organization_id integer, target_academic_term_id integer)
 RETURNS TABLE(allowed boolean, status text, source text, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  organization_scope text;
  organization_type_value text;
  enrollment_status_value text;
  participation_status text;
  participation_source text;
begin
  if target_student_id is null or target_student_id <= 0
    or target_organization_id is null or target_organization_id <= 0
    or target_academic_term_id is null or target_academic_term_id <= 0 then
    return query select false, null::text, null::text, 'invalid_request'::text;
    return;
  end if;

  select o.membership_scope, o.organization_type into organization_scope, organization_type_value
  from public.organizations o where o.id = target_organization_id;
  if not found then
    return query select false, null::text, null::text, 'organization_not_found'::text;
    return;
  end if;
  if organization_scope is null
     or organization_scope not in ('program', 'institution', 'manual') then
    return query select false, null::text, null::text, 'unsupported_membership_scope'::text;
    return;
  end if;
  if organization_type_value is null
     or organization_type_value not in ('departmental', 'non_departmental')
     or (organization_scope = 'program' and organization_type_value <> 'departmental')
     or (organization_scope = 'manual' and organization_type_value <> 'non_departmental') then
    return query select false, null::text, null::text, 'unsupported_organization_type'::text;
    return;
  end if;

  select ste.enrollment_status into enrollment_status_value
  from public.student_term_enrollments ste
  where ste.student_id = target_student_id
    and ste.academic_term_id = target_academic_term_id;
  if not found or enrollment_status_value <> 'enrolled' then
    return query select false, null::text, null::text, 'not_enrolled_for_term'::text;
    return;
  end if;

  select sot.status, sot.source into participation_status, participation_source
  from public.student_organization_terms sot
  where sot.student_id = target_student_id
    and sot.organization_id = target_organization_id
    and sot.academic_term_id = target_academic_term_id;
  if not found then
    return query select false, null::text, null::text, 'term_participation_missing'::text;
    return;
  end if;
  if participation_status = 'removed' then
    return query select false, participation_status, participation_source, 'term_participation_removed'::text;
    return;
  end if;
  return query select true, participation_status, participation_source, 'term_participation_active'::text;
end;
$function$

CREATE OR REPLACE FUNCTION private.kandid_guard_removed_election_child_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  row_data jsonb;
  previous_data jsonb;
  target_election_id bigint;
  target_position_id bigint;
  target_candidate_id bigint;
  target_publication_id uuid;
  removed timestamptz;
  rows_to_check jsonb[];
  item jsonb;
begin
  if tg_op = 'INSERT' then
    rows_to_check := array[to_jsonb(new)];
  elsif tg_op = 'DELETE' then
    rows_to_check := array[to_jsonb(old)];
  else
    rows_to_check := array[to_jsonb(old), to_jsonb(new)];
  end if;

  foreach row_data in array rows_to_check loop
    target_election_id := nullif(row_data ->> 'election_id', '')::bigint;
    if tg_table_name = 'candidates' then
      target_position_id := nullif(row_data ->> 'position_id', '')::bigint;
      select p.election_id into target_election_id
      from public.positions p where p.id = target_position_id;
    elsif tg_table_name = 'candidate_media' then
      target_candidate_id := nullif(row_data ->> 'candidate_id', '')::bigint;
      select p.election_id into target_election_id
      from public.candidates c join public.positions p on p.id = c.position_id
      where c.id = target_candidate_id;
    elsif tg_table_name = 'election_officer_publication_entries' then
      target_publication_id := nullif(row_data ->> 'publication_id', '')::uuid;
      select p.election_id into target_election_id
      from public.election_officer_publications p where p.id = target_publication_id;
    end if;

    if target_election_id is not null then
      removed := null;
      select e.removed_at into removed
      from public.elections e where e.id = target_election_id
      for key share;
      if removed is not null then
        raise exception using errcode = '42501', message = 'This election has been removed; related records are read-only.';
      end if;
    end if;
  end loop;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.kandid_get_student_ballot_candidates(p_election_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  caller_uid uuid := auth.uid();
  student_count integer;
  student_id_value integer;
  active_term_count integer;
  term_id_value integer;
  election_row record;
  participation_allowed boolean := false;
  manila_now timestamp without time zone;
  candidate_data jsonb;
begin
  if caller_uid is null or p_election_id is null or p_election_id <= 0 then
    raise exception using errcode='28000', message='Eligible Student authentication is required.';
  end if;
  select pg_catalog.count(*)::integer,pg_catalog.min(s.id)
    into student_count,student_id_value
    from public.students s where s.auth_user_id=caller_uid;
  if student_count<>1 or not exists (
    select 1 from public.students s where s.id=student_id_value
      and s.auth_user_id=caller_uid and s.status='active'
  ) then
    raise exception using errcode='42501', message='Ballot choices are unavailable.';
  end if;

  select e.id,e.organization_id,e.academic_term_id,e.electorate_policy_version,
         e.electorate_frozen_at,e.start_date,e.end_date,e.status::text as election_status
    into election_row
  from public.elections e
  where e.id=p_election_id and e.status='active' and e.removed_at is null;
  if not found then
    raise exception using errcode='42501', message='Ballot choices are unavailable.';
  end if;

  if election_row.start_date is null or election_row.end_date is null then
    return '[]'::jsonb;
  end if;
  manila_now := pg_catalog.timezone('Asia/Manila',pg_catalog.statement_timestamp());
  if manila_now < election_row.start_date or manila_now >= election_row.end_date then
    return '[]'::jsonb;
  end if;

  select pg_catalog.count(*)::integer,pg_catalog.min(t.id)
    into active_term_count,term_id_value
  from public.academic_terms t where t.status='active';
  if active_term_count<>1 then
    raise exception using errcode='42501', message='Ballot choices are unavailable.';
  end if;
  if election_row.academic_term_id is not null
     and election_row.academic_term_id is distinct from term_id_value then
    raise exception using errcode='42501', message='Ballot choices are unavailable.';
  end if;

  if election_row.electorate_policy_version=1 then
    if election_row.electorate_frozen_at is null
       or election_row.academic_term_id is null
       or term_id_value is distinct from election_row.academic_term_id
       or not exists (
         select 1 from public.student_term_enrollments ste
         where ste.student_id=student_id_value
           and ste.academic_term_id=term_id_value
           and ste.enrollment_status='enrolled'
       )
       or not exists (
         select 1 from private.election_eligible_voters ev
         where ev.election_id=p_election_id and ev.student_id=student_id_value
       ) then
      raise exception using errcode='42501', message='Ballot choices are unavailable.';
    end if;
  elsif election_row.electorate_policy_version<>0 then
    raise exception using errcode='42501', message='Ballot choices are unavailable.';
  end if;

  select coalesce(participation.allowed,false) into participation_allowed
  from public.resolve_student_organization_participation(
    student_id_value,election_row.organization_id,term_id_value
  ) participation;
  if not coalesce(participation_allowed,false) then
    raise exception using errcode='42501', message='Ballot choices are unavailable.';
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id',c.id,
    'position_id',c.position_id,
    'photo',c.photo,
    'students',pg_catalog.jsonb_build_object('first_name',s.first_name,'last_name',s.last_name,'photo_url',s.photo_url),
    'partylists',case when pl.id is null then null
      else pg_catalog.jsonb_build_object('name',pl.name,'logo_url',pl.logo_url) end
  ) order by p.display_order,p.id,c.id),'[]'::jsonb)
  into candidate_data
  from public.positions p
  join public.candidates c on c.position_id=p.id
  join public.students s on s.id=c.student_id
  left join public.partylists pl on pl.id=c.partylist_id
    and pl.organization_id=election_row.organization_id
    and (pl.election_id is null or pl.election_id=p_election_id)
  where p.election_id=p_election_id and p.status='active';
  return candidate_data;
end;
$function$
